 p_id=>wwv_flow_imp.id(60002100000052)
,p_plug_name=>'Course builder'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(237400365074697960)
,p_plug_display_sequence=>10
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :P111_COURSE_ID is not null then',
'  for c in (select course_code, title_en, status from v_lms_my_courses where course_id = :P111_COURSE_ID) loop',
'    htp.p(''<p class="lms-builder-title"><strong>'' || apex_escape.html(c.course_code || '' - '' || c.title_en) || ''</strong> (''',
'       || apex_escape.html(c.status) || '')</p>'');',
'  end loop;',
'  htp.p(''<nav class="lms-steps" aria-label="Course builder steps">'' || case when 111 = 111 then ''<strong>1. Basic information</strong>'' else ''<a href="'' || apex_page.get_url(p_page => 111, p_items => ''P111_COURSE_ID'', p_values => :P111_COURSE_ID) || ''">1. Basic information</a>'' end || '' &rsaquo; '' || case when 112 = 111 then ''<strong>2. Modules</strong>'' else ''<a href="'' || apex_page.get_url(p_page => 112, p_items => ''P112_COURSE_ID'', p_values => :P111_COURSE_ID) || ''">2. Modules</a>'' end || '' &rsaquo; '' || case when 113 = 111 then ''<strong>3. Lessons</strong>'' else ''<a href="'' || apex_page.get_url(p_page => 113, p_items => ''P113_COURSE_ID'', p_values => :P111_COURSE_ID) || ''">3. Lessons</a>'' end || '' &rsaquo; '' || case when 114 = 111 then ''<strong>4. Assessments</strong>'' else ''<a href="'' || apex_page.get_url(p_page => 114, p_items => ''P114_COURSE_ID'', p_values => :P111_COURSE_ID) || ''">4. Assessments</a>'' '||'end || '' &rsaquo; '' || case when 115 = 111 then ''<strong>5. Completion rules</strong>'' else ''<a href="'' || apex_page.get_url(p_page => 115, p_items => ''P115_COURSE_ID'', p_values => :P111_COURSE_ID) || ''">5. Completion rules</a>'' end || '' &rsaquo; '' || case when 116 = 111 then ''<strong>6. Review and publish</strong>'' else ''<a href="'' || apex_page.get_url(p_page => 116, p_items => ''P116_COURSE_ID'', p_values => :P111_COURSE_ID) || ''">6. Review and publish</a>'' end || ''</nav>'');',
'end if;'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_plug_query_num_rows=>15
);
