wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(60002100000077)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :P111_COURSE_ID is not null then',
'  select course_code, title_en, title_ar, category_id, delivery_method, difficulty, duration_minutes, language_code, capacity,',
'         approval_required, available_from, available_to, enroll_deadline, description_en, description_ar, objectives_en,',
'         objectives_ar, thumbnail_ref, completion_rule, certificate_eligible, status, row_version',
'    into :P111_COURSE_CODE, :P111_TITLE_EN, :P111_TITLE_AR, :P111_CATEGORY_ID, :P111_DELIVERY_METHOD, :P111_DIFFICULTY,',
'         :P111_DURATION_MINUTES, :P111_LANGUAGE_CODE, :P111_CAPACITY, :P111_APPROVAL_REQUIRED, :P111_AVAILABLE_FROM,',
'         :P111_AVAILABLE_TO, :P111_ENROLL_DEADLINE, :P111_DESCRIPTION_EN, :P111_DESCRIPTION_AR, :P111_OBJECTIVES_EN,',
'         :P111_OBJECTIVES_AR, :P111_THUMBNAIL_REF, :P111_COMPLETION_RULE, :P111_CERT_ELIGIBLE, :P111_STATUS, :P111_ROW_VERSION',
'    from v_lms_course_edit where course_id = :P111_COURSE_ID;',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>60002100000077
);
