 p_id=>wwv_flow_imp.id(60002100000081)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Save'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :P111_COURSE_ID is null then',
'  :P111_COURSE_ID := lms_course_pkg.create_course(upper(:P111_COURSE_CODE), :P111_TITLE_EN, :P111_TITLE_AR, :P111_CATEGORY_ID,',
'                     :P111_DELIVERY_METHOD, :P111_DIFFICULTY, :P111_DURATION_MINUTES, :P111_LANGUAGE_CODE, :P111_CAPACITY,',
'                     :P111_APPROVAL_REQUIRED, ''LESSONS'', ''N'');',
'  select row_version into :P111_ROW_VERSION from v_lms_course_edit where course_id = :P111_COURSE_ID;',
'  :P111_COMPLETION_RULE := ''LESSONS''; :P111_CERT_ELIGIBLE := ''N'';',
'end if;',
'lms_course_pkg.update_course(:P111_COURSE_ID, :P111_ROW_VERSION, :P111_TITLE_EN, :P111_TITLE_AR, :P111_CATEGORY_ID, :P111_DIFFICULTY,',
'                             :P111_DURATION_MINUTES, :P111_CAPACITY, :P111_APPROVAL_REQUIRED, nvl(:P111_COMPLETION_RULE, ''LESSONS''),',
'                             nvl(:P111_CERT_ELIGIBLE, ''N''), :P111_AVAILABLE_FROM, :P111_AVAILABLE_TO, :P111_ENROLL_DEADLINE);',
'select row_version into :P111_ROW_VERSION from v_lms_course_edit where course_id = :P111_COURSE_ID;',
'lms_course_pkg.set_course_text(:P111_COURSE_ID, :P111_ROW_VERSION, :P111_DESCRIPTION_EN, :P111_DESCRIPTION_AR,',
'                               :P111_OBJECTIVES_EN, :P111_OBJECTIVES_AR, :P111_THUMBNAIL_REF);'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(60002100000079)
,p_process_success_message=>'Course saved.'
,p_internal_uid=>60002100000081
);
