begin
wwv_flow_imp_page.create_page(
 p_id=>112
,p_name=>'Course: modules'
,p_alias=>'INSTRUCTOR-MODULES'
,p_step_title=>'Course: modules'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#'
,p_required_role=>wwv_flow_imp.id(60005000000011)
,p_protection_level=>'C'
,p_page_component_map=>'18'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(60002100000083)
,p_plug_name=>'Course builder'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(237400365074697960)
,p_plug_display_sequence=>10
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :P112_COURSE_ID is not null then',
'  for c in (select course_code, title_en, status from v_lms_my_courses where course_id = :P112_COURSE_ID) loop',
'    htp.p(''<p class="lms-builder-title"><strong>'' || apex_escape.html(c.course_code || '' - '' || c.title_en) || ''</strong> (''',
